test("EN1995 complete neutral state agrees with independent JSON schema",()=>{expect(new Ajv({strict:false}).validate(schema,fixture)).toBe(true)});
test("EN1995 owning facade exposes complete relational snapshot directions",()=>{expect(Object.hasOwn(snapshot,"en1995SnapshotToSqliteDatabase")).toBe(true);expect(Object.hasOwn(snapshot,"en1995SnapshotFromSqliteDatabase")).toBe(true)});
test("EN1995 root arrays enforce complete closed owned member and connection shapes",()=>{const ajv=new Ajv({strict:false});expect(ajv.validate(schema,{...fixture,members:[{}]})).toBe(false);expect(ajv.validate(schema,{...fixture,connections:[{}]})).toBe(false);expect(ajv.validate(schema,{...fixture,members:[{...fixture.members[0],unknown:true}]})).toBe(false);expect(ajv.validate(schema,{...fixture,connections:[{...fixture.connections[0],unknown:true}]})).toBe(false)});

function ownedFixture():En1995SqliteSnapshot{
 const f=fixture;return{annex:f.annex as En1995SqliteSnapshot["annex"],members:f.members.map(m=>({...m,role:m.role as En1995SqliteMember["role"],support:m.support as En1995SqliteMember["support"],bM:binary64(m.bM),hM:binary64(m.hM),spanM:binary64(m.spanM),supportLengthM:binary64(m.supportLengthM),bearingLengthM:binary64(m.bearingLengthM),bucklingLengthYM:binary64(m.bucklingLengthYM),bucklingLengthZM:binary64(m.bucklingLengthZM),lateralRestraintSpacingM:binary64(m.lateralRestraintSpacingM),notchDepthM:binary64(m.notchDepthM),notchDistanceM:binary64(m.notchDistanceM),mCritNm:binary64(m.mCritNm),massKgPerM:binary64(m.massKgPerM),massKgPerM2:binary64(m.massKgPerM2),dampingXi:binary64(m.dampingXi),fireDurationS:binary64(m.fireDurationS),bridgeNObs:binary64(m.bridgeNObs),bridgeTLYears:binary64(m.bridgeTLYears),bridgeBeta:binary64(m.bridgeBeta),bridgeA:binary64(m.bridgeA),bridgeB:binary64(m.bridgeB),bridgeCrowdPerM2:binary64(m.bridgeCrowdPerM2),actions:m.actions.map(a=>({...a,qLineNPerM:binary64(a.qLineNPerM),fPointN:binary64(a.fPointN),mKNm:binary64(a.mKNm),vKN:binary64(a.vKN),nKN:binary64(a.nKN),nTKN:binary64(a.nTKN),fC90KN:binary64(a.fC90KN)}))})),connections:f.connections.map(c=>({...c,diameterM:binary64(c.diameterM),spacingM:binary64(c.spacingM),edgeDistanceM:binary64(c.edgeDistanceM),endDistanceM:binary64(c.endDistanceM),t1M:binary64(c.t1M),t2M:binary64(c.t2M),steelPlateThicknessM:binary64(c.steelPlateThicknessM),fUK:binary64(c.fUK),actions:c.actions.map(a=>({...a,fKN:binary64(a.fKN)}))}))};
}
function nativeWord(value:number):bigint{const b=Buffer.alloc(8);b.writeDoubleBE(value);return b.readBigUInt64BE()}
function setEveryWord(s:En1995SqliteSnapshot,v:Binary64):void{
 for(const m of s.members){m.bM=v;m.hM=v;m.spanM=v;m.supportLengthM=v;m.bearingLengthM=v;m.bucklingLengthYM=v;m.bucklingLengthZM=v;m.lateralRestraintSpacingM=v;m.notchDepthM=v;m.notchDistanceM=v;m.mCritNm=v;m.massKgPerM=v;m.massKgPerM2=v;m.dampingXi=v;m.fireDurationS=v;m.bridgeNObs=v;m.bridgeTLYears=v;m.bridgeBeta=v;m.bridgeA=v;m.bridgeB=v;m.bridgeCrowdPerM2=v;for(const a of m.actions){a.qLineNPerM=v;a.fPointN=v;a.mKNm=v;a.vKN=v;a.nKN=v;a.nTKN=v;a.fC90KN=v}}
 for(const c of s.connections){c.diameterM=v;c.spacingM=v;c.edgeDistanceM=v;c.endDistanceM=v;c.t1M=v;c.t2M=v;c.steelPlateThicknessM=v;c.fUK=v;for(const a of c.actions)a.fKN=v}
