fn sqlite_snapshot_din4108_independent_sqlite_nested_joins_and_domain_edits(){
    use std::{io::Write,process::{Command,Stdio}};
    let mut expected=fixture();let bytes=export_sqlite_database(&database(&expected),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
    let script="import{Database}from'bun:sqlite';import{Buffer}from'node:buffer';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const segments=db.query('SELECT e.ordinal AS element,l.ordinal AS layer,s.ordinal AS segment FROM din4108_segment s JOIN din4108_layer l ON l.id=s.layer_id JOIN din4108_element e ON e.id=l.element_id ORDER BY e.ordinal,l.ordinal,s.ordinal').all();if(segments.length!==2||segments[0].element!==0||segments[0].layer!==0||segments[0].segment!==0||segments[1].segment!==1)throw Error('nested segment ownership');const windows=db.query('SELECT z.ordinal AS zone,w.ordinal AS window FROM din4108_window w JOIN din4108_zone z ON z.id=w.zone_id ORDER BY z.ordinal,w.ordinal').all();if(windows.length!==2||windows[0].zone!==0||windows[1].window!==1)throw Error('nested window ownership');const b=Buffer.alloc(8);b.writeDoubleBE(0.625);db.run(\"UPDATE din4108_segment SET fraction=0.625,fraction_ieee754_bits=?,fraction_ieee754_class='finite',material_logical_id='Geändert 世界' WHERE id=1\",[BigInt.asIntN(64,b.readBigUInt64BE())]);db.run(\"UPDATE din4108_element SET zone_logical_id='unresolved zone' WHERE id=1\");db.run(\"UPDATE din4108_document SET climate_zone='Zone1',has_mechanical_ventilation=0,bb2_details_conform=1\");await Bun.write(Bun.stdout,db.serialize());db.close();";
    let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));expected.elements[0].layers[0].segments[0].fraction=0.625;expected.elements[0].layers[0].segments[0].material_id="Geändert 世界".into();expected.elements[0].zone_id="unresolved zone".into();expected.climate_zone=crate::document::ClimateZoneDe::Zone1;expected.has_mechanical_ventilation=false;expected.bb2_details_conform=true;assert_eq!(Din4108Snapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);
}

