 const ajv=new Ajv({strict:false});for(const value of choices.invalidUnsigned32){expect(ajv.validate(schema,{...fixture,storeys:value})).toBe(false);expect(ajv.validate(schema,{...fixture,walls:[{...fixture.walls[0]!,fireReiMin:value}]})).toBe(false)}for(const value of choices.validUnsigned32){expect(ajv.validate(schema,{...fixture,storeys:value})).toBe(true);expect(ajv.validate(schema,{...fixture,walls:[{...fixture.walls[0]!,fireReiMin:value}]})).toBe(true)}
 for(const value of choices.invalidUnsigned8)expect(ajv.validate(schema,{...fixture,walls:[{...fixture.walls[0]!,supportSides:value}]})).toBe(false);for(const value of choices.validUnsigned8)expect(ajv.validate(schema,{...fixture,walls:[{...fixture.walls[0]!,supportSides:value}]})).toBe(true);
 for(const field of["annex","masonryClass","designSituation"])expect(ajv.validate(schema,{...fixture,[field]:"unknown"})).toBe(false);for(const field of["wallType","unitGroup","unitMaterial","mortarType","mortarClass","exposure"])expect(ajv.validate(schema,{...fixture,walls:[{...fixture.walls[0]!,[field]:"unknown"}]})).toBe(false);
});
test("EN1996 independent SQLite queries ordered masonry relationships and applies semantic edits",async()=>{
 expect(EN1996_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text());const expected=ownedFixture(),database=await en1996SnapshotToSqliteDatabase(expected);expect(await en1996SnapshotFromSqliteDatabase(database)).toEqual(expected);
 const db=Database.deserialize(await exportSqliteDatabase(database));try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query("SELECT w.label_de,c.design_situation,l.ordinal,l.force_n FROM en1996_wall w JOIN en1996_load_case c ON c.wall_id=w.id JOIN en1996_concentrated_load l ON l.load_case_id=c.id WHERE w.id=1 ORDER BY c.ordinal,l.ordinal").all()).toEqual([{label_de:fixture.walls[0]!.labelDe,design_situation:fixture.walls[0]!.loadCases[0]!.designSituation,ordinal:0,force_n:35000.25},{label_de:fixture.walls[0]!.labelDe,design_situation:fixture.walls[0]!.loadCases[0]!.designSituation,ordinal:1,force_n:-35000.25}]);
  db.run("UPDATE en1996_concentrated_load SET force_n=42.5,force_n_ieee754_bits=?,force_n_ieee754_class='finite' WHERE id=1",[BigInt.asIntN(64,nativeWord(42.5))]);db.run("UPDATE en1996_wall SET label_de='Geändert 世界',support_sides=254 WHERE id=1");db.run("UPDATE en1996_document SET design_situation='Transient',storeys=4294967294");expected.walls[0]!.loadCases[0]!.concentrated[0]!.forceN={bits:nativeWord(42.5)};expected.walls[0]!.labelDe="Geändert 世界";expected.walls[0]!.supportSides=254;expected.designSituation="Transient";expected.storeys=4294967294;expect(await en1996SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))).toEqual(expected)}finally{db.close()}
});
for(const text of words.ieee754Binary64Bits)test(`EN1996 all thirty-two numeric domains retain word ${text}`,async()=>{
 const expected=ownedFixture(),v={bits:BigInt(text)};setEveryWord(expected,v);const db=Database.deserialize(await exportSqliteDatabase(await en1996SnapshotToSqliteDatabase(expected)),{safeIntegers:true});try{const b=Buffer.alloc(8);b.writeBigUInt64BE(v.bits);const scalar=b.readDoubleBE(),r=db.query("SELECT thickness_m,thickness_m_ieee754_bits FROM en1996_wall WHERE id=1").get()as{thickness_m:number|null;thickness_m_ieee754_bits:bigint};expect(BigInt.asUintN(64,r.thickness_m_ieee754_bits)).toBe(v.bits);expect(r.thickness_m).toBe(Number.isNaN(scalar)?null:scalar);expect(await en1996SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))).toEqual(expected)}finally{db.close()}
});
for(const field of["annex","masonryClass","designSituation"]as const)for(const value of choices[field])test(`EN1996 preserves root ${field} ${value}`,async()=>{const expected={...ownedFixture(),[field]:value}as En1996SqliteSnapshot;expect(await en1996SnapshotFromSqliteDatabase(await importSqliteDatabase(await exportSqliteDatabase(await en1996SnapshotToSqliteDatabase(expected))))).toEqual(expected)});
for(const field of["wallType","unitGroup","unitMaterial","mortarType","mortarClass","exposure"]as const)for(const value of choices[field])test(`EN1996 preserves wall ${field} ${value}`,async()=>{const expected=ownedFixture();expected.walls[0]={...expected.walls[0]!,[field]:value}as En1996SqliteWall;expect(await en1996SnapshotFromSqliteDatabase(await importSqliteDatabase(await exportSqliteDatabase(await en1996SnapshotToSqliteDatabase(expected))))).toEqual(expected)});
test("EN1996 empty collections retain every independently queryable table",async()=>{const expected={...ownedFixture(),walls:[]},database=await en1996SnapshotToSqliteDatabase(expected);expect(database.tables.length).toBe(5);expect(await en1996SnapshotFromSqliteDatabase(await importSqliteDatabase(await exportSqliteDatabase(database)))).toEqual(expected)});
test("EN1996 rejects malformed choices booleans unsigned widths ordinals parent identities and words",async()=>{
 const database=await en1996SnapshotToSqliteDatabase(ownedFixture());for(const sql of["UPDATE en1996_document SET storeys=4294967296","UPDATE en1996_document SET annex='unknown'","UPDATE en1996_document SET masonry_class='unknown'","UPDATE en1996_document SET design_situation='unknown'","UPDATE en1996_wall SET support_sides=256 WHERE id=1","UPDATE en1996_wall SET fire_rei_min=-1 WHERE id=1","UPDATE en1996_wall SET wall_type='unknown' WHERE id=1","UPDATE en1996_wall SET unit_group='unknown' WHERE id=1","UPDATE en1996_wall SET unit_material='unknown' WHERE id=1","UPDATE en1996_wall SET mortar_type='unknown' WHERE id=1","UPDATE en1996_wall SET mortar_class='unknown' WHERE id=1","UPDATE en1996_wall SET exposure='unknown' WHERE id=1","UPDATE en1996_wall SET reinforced=2 WHERE id=1","UPDATE en1996_wall SET document_id=99 WHERE id=1","UPDATE en1996_wall SET ordinal=0 WHERE id=2","UPDATE en1996_opening SET wall_id=99 WHERE id=1","UPDATE en1996_opening SET ordinal=99 WHERE id=1","UPDATE en1996_load_case SET wall_id=99 WHERE id=1","UPDATE en1996_load_case SET ordinal=0 WHERE id=2","UPDATE en1996_concentrated_load SET load_case_id=99 WHERE id=1","UPDATE en1996_concentrated_load SET ordinal=99 WHERE id=1","UPDATE en1996_wall SET thickness_m_ieee754_class='nan' WHERE id=1","DELETE FROM en1996_document"]){const db=Database.deserialize(await exportSqliteDatabase(database));try{db.run("PRAGMA ignore_check_constraints=ON");db.run(sql);await expect(en1996SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))).rejects.toThrow()}finally{db.close()}}
 await expect(en1996SnapshotToSqliteDatabase(ownedFixture(),{maxRows:1})).rejects.toThrow();await expect(en1996SnapshotFromSqliteDatabase(database,{maxValueBytes:0})).rejects.toThrow();
});
test("EN1996 initial and nested expensive operations support cancellation and owned value limits",async()=>{
 const expected=ownedFixture(),initial=new AbortController();initial.abort();await expect(en1996SnapshotToSqliteDatabase(expected,{signal:initial.signal})).rejects.toHaveProperty("kind","canceled");const database=await en1996SnapshotToSqliteDatabase(expected);await expect(en1996SnapshotFromSqliteDatabase(database,{signal:initial.signal})).rejects.toHaveProperty("kind","canceled");expected.walls[0]!.loadCases[0]!.concentrated=Array.from({length:controls.entityCount},()=>({...expected.walls[0]!.loadCases[0]!.concentrated[0]!}));const large=await en1996SnapshotToSqliteDatabase(expected);
 for(const phase of["projectSnapshot","reconstructSnapshot"]as const){const c=new AbortController();let reached=false;const options={signal:c.signal,onProgress:(event:{phase:string;completed:number})=>{if(event.phase===phase&&event.completed>=controls.cancelAt){reached=true;c.abort()}}};await expect(phase==="projectSnapshot"?en1996SnapshotToSqliteDatabase(expected,options):en1996SnapshotFromSqliteDatabase(large,options)).rejects.toHaveProperty("kind","canceled");expect(reached).toBe(true)}
 expected.walls[0]!.labelDe="x".repeat(controls.largeTextBytes);await expect(en1996SnapshotToSqliteDatabase(expected,{maxValueBytes:controls.largeTextBytes-1})).rejects.toThrow();const c=new AbortController();let reached=false;await expect(en1996SnapshotToSqliteDatabase(expected,{signal:c.signal,onProgress:event=>{if(event.phase==="projectSnapshot"&&event.completed>0&&event.total===0){reached=true;c.abort()}}})).rejects.toHaveProperty("kind","canceled");expect(reached).toBe(true);
});

