test("EN1994 independent SQLite joins all composite components and edits authoritative semantic values",async()=>{
 const expected=ownedFixture(),database=await en1994SnapshotToSqliteDatabase(expected);expect(EN1994_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text());expect(await en1994SnapshotFromSqliteDatabase(database)).toEqual(expected);
 const db=Database.deserialize(await exportSqliteDatabase(database));try{
  expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);
  expect(db.query("SELECT b.ordinal,a.ordinal AS action,s.designation,t.count_per_rib,h.ribs_parallel_to_beam FROM en1994_beam b JOIN en1994_beam_steel s ON s.beam_id=b.id JOIN en1994_beam_studs t ON t.beam_id=b.id JOIN en1994_beam_sheeting h ON h.beam_id=b.id JOIN en1994_beam_action a ON a.beam_id=b.id ORDER BY b.ordinal,a.ordinal").all()).toEqual(fixture.beams.flatMap((b,ordinal)=>b.actions.map((_,action)=>({ordinal,action,designation:b.steel.designation,count_per_rib:b.studs.countPerRib,ribs_parallel_to_beam:Number(b.sheeting.ribsParallelToBeam)}))));
  expect(db.query("SELECT c.ordinal,a.ordinal AS action,a.m_k_nm FROM en1994_column c JOIN en1994_column_action a ON a.column_id=c.id ORDER BY c.ordinal,a.ordinal").all()).toEqual(fixture.columns.flatMap((c,ordinal)=>c.actions.map((a,action)=>({ordinal,action,m_k_nm:a.mKNm}))));
  expect(db.query("SELECT s.ordinal,h.profile,a.ordinal AS action FROM en1994_slab s JOIN en1994_slab_sheeting h ON h.slab_id=s.id JOIN en1994_slab_action a ON a.slab_id=s.id ORDER BY s.ordinal,a.ordinal").all()).toEqual(fixture.slabs.flatMap((s,ordinal)=>s.actions.map((_,action)=>({ordinal,profile:s.sheeting.profile,action}))));
  db.run("UPDATE en1994_beam_steel SET designation=?,height_m=0.625,height_m_ieee754_bits=?,height_m_ieee754_class='finite' WHERE id=1",["Geändert 世界\u0000",BigInt.asIntN(64,nativeWord(0.625))]);db.run("UPDATE en1994_beam_studs SET count_per_rib=0,total_count=4294967295 WHERE id=1");db.run("UPDATE en1994_beam_sheeting SET ribs_parallel_to_beam=0 WHERE id=1");db.run("UPDATE en1994_document SET annex='De'");expected.beams[0]!.steel.designation="Geändert 世界\u0000";expected.beams[0]!.steel.heightM={bits:nativeWord(0.625)};expected.beams[0]!.studs.countPerRib=0;expected.beams[0]!.studs.totalCount=4294967295;expected.beams[0]!.sheeting.ribsParallelToBeam=false;expected.annex="De";expect(await en1994SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))).toEqual(expected);
 }finally{db.close()}
});
for(const text of words.ieee754Binary64Bits)test("EN1994 every binary64 field retains independent word "+text,async()=>{
 const expected=ownedFixture(),word={bits:BigInt(text)};everyWord(expected,word);const db=Database.deserialize(await exportSqliteDatabase(await en1994SnapshotToSqliteDatabase(expected)),{safeIntegers:true});try{
  const bytes=Buffer.alloc(8);bytes.writeBigUInt64BE(word.bits);const scalar=bytes.readDoubleBE();let checked=0;for(const suffix of ["document","beam","beam_steel","beam_sheeting","beam_studs","beam_action","column","column_action","slab","slab_sheeting","slab_action"]){const name="en1994_"+suffix,columns=db.query("PRAGMA table_info("+name+")").all() as {name:string}[];for(const column of columns.filter(c=>c.name.endsWith("_ieee754_bits"))){const field=column.name.slice(0,-13);for(const row of db.query("SELECT "+field+" AS value,"+column.name+" AS bits FROM "+name).all() as {value:number|null;bits:bigint}[]){expect(BigInt.asUintN(64,row.bits)).toBe(word.bits);expect(row.value).toBe(Number.isNaN(scalar)?null:scalar);checked++}}}expect(checked).toBe(61);expect(await en1994SnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(db.serialize())))).toEqual(expected)
 }finally{db.close()}
});
