test("EN1994 expensive action collections and owned text support progress cancellation and bounds",async()=>{
 const expected=ownedFixture(),initial=new AbortController();initial.abort();await expect(en1994SnapshotToSqliteDatabase(expected,{signal:initial.signal})).rejects.toHaveProperty("kind","canceled");const database=await en1994SnapshotToSqliteDatabase(expected);await expect(en1994SnapshotFromSqliteDatabase(database,{signal:initial.signal})).rejects.toHaveProperty("kind","canceled");expected.beams[0]!.actions=Array.from({length:controls.entityCount},()=>({...expected.beams[0]!.actions[0]!}));const large=await en1994SnapshotToSqliteDatabase(expected);
 for(const phase of ["projectSnapshot","reconstructSnapshot"] as const){const c=new AbortController();let reached=false;const options={signal:c.signal,onProgress:(event:{phase:string;completed:number})=>{if(event.phase===phase&&event.completed>=controls.cancelAt){reached=true;c.abort()}}};await expect(phase==="projectSnapshot"?en1994SnapshotToSqliteDatabase(expected,options):en1994SnapshotFromSqliteDatabase(large,options)).rejects.toHaveProperty("kind","canceled");expect(reached).toBe(true)}
 expected.structureKind="x".repeat(controls.largeTextBytes);await expect(en1994SnapshotToSqliteDatabase(expected,{maxValueBytes:controls.largeTextBytes-1})).rejects.toThrow();const c=new AbortController();let reached=false;await expect(en1994SnapshotToSqliteDatabase(expected,{signal:c.signal,onProgress:event=>{if(event.phase==="projectSnapshot"&&event.completed>0&&event.total===0){reached=true;c.abort()}}})).rejects.toHaveProperty("kind","canceled");expect(reached).toBe(true)
});

