/** 🔬️ Queries the full independent two-annex corpus using a separate physical SQLite implementation. */
async function en1997CompleteIndependentOracle(input:Uint8Array,mode:string,annex:string):Promise<Uint8Array>{
 const script="import{Database}from'bun:sqlite';import{deepStrictEqual,ok}from'node:assert';import Ajv from'ajv';
const expected=await Bun.file(process.argv[1]).json(),schema=await Bun.file(process.argv[2]).json(),mode=process.argv[3],encoding=process.argv[4],annex=process.argv[5];
ok(new Ajv({strict:true}).compile(schema)(expected),'closed independent fixture');
const variant=expected.variants.find(value=>value.annex===annex);ok(variant,'literal annex');
const database=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true}),names=variant.tables.map(table=>table.name).sort();
function verify(){
 deepStrictEqual(database.query('PRAGMA integrity_check').all(),[{integrity_check:'ok'}]);deepStrictEqual(database.query('PRAGMA foreign_key_check').all(),[]);
 const roster=names.slice(),metadata=expected.metadata;
 if(encoding!=='none'){ok(['binary','text'].includes(encoding));roster.push(metadata.table);deepStrictEqual(database.query('PRAGMA table_info('+metadata.table+')').all().map(row=>row.name),metadata.columns);deepStrictEqual(database.query('SELECT '+metadata.columns.join(',')+' FROM '+metadata.table+' ORDER BY id').all().map(row=>metadata.columns.map(column=>typeof row[column]==='bigint'?Number(row[column]):row[column])),metadata.rowsByEncoding[encoding==='binary'?'Binary':'Text']);}
 deepStrictEqual(database.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all().map(row=>row.name),roster.sort());
 const actual=new Map(),identities=new Map(),prefix={en1997_soil_layer:'layer',en1997_footing:'footing',en1997_pile:'pile',en1997_retaining_wall:'wall',en1997_slope:'slope',en1997_uplift_case:'uplift'};
 for(const table of variant.tables){
  deepStrictEqual(database.query('PRAGMA table_info('+table.name+')').all().map(row=>row.name),table.columns);
  const order=table.columns.includes('footing_id')?'footing_id,ordinal':table.columns.includes('pile_id')?'pile_id,ordinal':table.columns.includes('ordinal')?'ordinal':'id';
  const rows=database.query('SELECT rowid AS __rowid,'+table.columns.join(',')+' FROM '+table.name+' ORDER BY '+order).all();
  deepStrictEqual(rows.length,table.count);deepStrictEqual(new Set(rows.map(row=>String(row.id))).size,rows.length);
  actual.set(table.name,rows);const ids=new Map(),ordinals=new Map();
  for(const row of rows){ok(row.id>0n);deepStrictEqual(row.__rowid,row.id);
   let identity;
   if(table.name==='en1997_document'){deepStrictEqual(row.id,1n);identity='document';}
   else{
    const parentTable=table.columns.includes('footing_id')?'en1997_footing':table.columns.includes('pile_id')?'en1997_pile':'en1997_document';
    const parentColumn=parentTable==='en1997_footing'?'footing_id':parentTable==='en1997_pile'?'pile_id':'document_id';
    const parent=identities.get(parentTable).get(String(row[parentColumn]));ok(parent,'actual owned parent');
    const ordinal=ordinals.get(parent)||0;deepStrictEqual(row.ordinal,BigInt(ordinal));ordinals.set(parent,ordinal+1);
    identity=parentTable==='en1997_footing'?parent+'/load'+ordinal:parentTable==='en1997_pile'?parent+'/test'+ordinal:prefix[table.name]+ordinal;
   }
   ids.set(String(row.id),identity);
  }
  identities.set(table.name,ids);
 }
 let totalRows=0,totalCells=0;
 for(const table of variant.tables){
  const rows=actual.get(table.name),values=rows.map(row=>table.columns.map(column=>{
   const value=row[column];if(column==='id')return identities.get(table.name).get(String(value));
   if(column==='document_id')return identities.get('en1997_document').get(String(value));
   if(column==='footing_id')return identities.get('en1997_footing').get(String(value));
   if(column==='pile_id')return identities.get('en1997_pile').get(String(value));
   if(value===null)return null;if(column.endsWith('_bits'))return String(value);if(typeof value==='bigint')return Number(value);if(typeof value==='number'&&value===0)return 0;return value;
  }));deepStrictEqual(values,table.rows,table.name+' all semantic cells');totalRows+=rows.length;totalCells+=rows.length*table.columns.length;
 }
 deepStrictEqual(totalRows,expected.totalRows);deepStrictEqual(totalCells,expected.totalCells);
 console.error('[DEBUG] EN1997 independent complete SQLite annex='+annex+' tables='+names.length+' rows='+totalRows+' cells='+totalCells+' mode='+mode+' encoding='+encoding);
}
function edited(){const table=variant.tables.find(table=>table.name===expected.edit.table);deepStrictEqual(table.rows[0],expected.edit.before);table.rows[0]=expected.edit.after;}
try{
 if(mode==='edited'){edited();verify();}
 else{verify();if(mode==='edit'){
  deepStrictEqual(Number(database.query("UPDATE en1997_pile_test_profile SET shaft_resistance=8.0,shaft_resistance_ieee754_bits=4620693217682128896,shaft_resistance_ieee754_class='finite' WHERE ordinal=0 AND pile_id=(SELECT id FROM en1997_pile WHERE document_id=1 AND ordinal=0)").run().changes),1);
  deepStrictEqual(database.query("SELECT t.shaft_resistance,t.shaft_resistance_ieee754_bits,t.shaft_resistance_ieee754_class FROM en1997_pile_test_profile t JOIN en1997_pile p ON t.pile_id=p.id WHERE p.document_id=1 AND p.ordinal=0 AND t.ordinal=0").get(),{shaft_resistance:8,shaft_resistance_ieee754_bits:4620693217682128896n,shaft_resistance_ieee754_class:'finite'});
  edited();verify();
 }else deepStrictEqual(mode,'original');}
 await Bun.write(Bun.stdout,database.serialize());
}finally{database.close();}";
 const child=Bun.spawn(["bun","-e",script,en1997IndependentFixturePath(new URL("../../🧫️fixtures/🪶️sqlite/🔬️independent/🔣️.json",import.meta.url)),en1997IndependentFixturePath(new URL("../../🧫️fixtures/🪶️sqlite/🔬️independent/🧬️schema/🔣️.json",import.meta.url)),mode,"none",annex],{stdin:input,stdout:"pipe",stderr:"pipe"});
 const[output,diagnostics,status]=await Promise.all([new Response(child.stdout).arrayBuffer(),new Response(child.stderr).text(),child.exited]);if(status!==0)throw Error(diagnostics);console.error(diagnostics);return new Uint8Array(output);
}
test("EN1997 all 210 independent SQL cells and coherent nested edit preserve both full annex owners",async()=>{
 for(const annex of ["En","De"]as const){
  const original=owned(),expected=owned();original.annex=annex;expected.annex=annex;expected.piles[0]!.testProfiles[0]!.shaftResistance=binary64(8);
  const edited=await en1997CompleteIndependentOracle(await exportSqliteDatabase(await en1997SnapshotToSqliteDatabase(original)),"edit",annex);
  const actual=await en1997SnapshotFromSqliteDatabase(await importSqliteDatabase(edited));expect(actual).toEqual(expected);
  await en1997CompleteIndependentOracle(await exportSqliteDatabase(await en1997SnapshotToSqliteDatabase(actual)),"edited",annex);
  console.log("[DEBUG] EN1997 Source independently edited complete owner annex="+annex+" tables=9 rows=9 cells=210");
 }
});

