/// 🔬️ Measures every physical domain cell with an independent SQLite implementation.
fn en1997_independent_native_extent(snapshot:&En1997Snapshot)->(usize,usize){
 use std::{io::Write,process::{Command,Stdio}};
 let bytes=export_sqlite_database(&project(snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
 let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});let rows=0,bytes=0;for(const t of d.query("SELECT name FROM sqlite_schema WHERE type='table'").all()){for(const row of d.query('SELECT * FROM '+t.name).all()){rows++;for(const value of Object.values(row)){bytes+=value===null?0:typeof value==='string'?Buffer.byteLength(value):8;}}}d.close();await Bun.write(Bun.stdout,JSON.stringify([rows,bytes]));"#;
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));serde_json::from_slice(&output.stdout).unwrap()
}

